INSERT INTO `hospitals` VALUES (1,'Apollo Hospital','apollo-hospital-delhi','Sarita Vihar','New Delhi','Delhi','India',4.90,'Multi-Specialty','Apollo Hospitals, Delhi is a state-of-the-art multi-specialty tertiary care hospital.','https://images.unsplash.com/photo-1587351021759-3e566b9af923?auto=format&fit=crop&q=80&w=2070','JCI, NABH','Sarita Vihar, Delhi Mathura Road, New Delhi - 110076','+91-11-26925858','info@apollo.com','https://delhi.apollohospitals.com',1996,710,NULL,'25 km',1,'2025-12-03 11:58:33','2025-12-03 11:58:33'),(2,'Medanta - The Medicity','medanta-the-medicity','Sector 38','Gurgaon','Haryana','India',4.80,'Multi-Specialty','Medanta is one of India\'s largest multi-super specialty institutes located in Gurgaon.','https://images.unsplash.com/photo-1519494026892-80bbd2d6fd0d?auto=format&fit=crop&q=80&w=2053','JCI, NABH','CH Baktawar Singh Road, Sector 38, Gurugram, Haryana 122001','+91-124-4141414','info@medanta.org','https://www.medanta.org',2009,1250,NULL,'18 km',1,'2025-12-03 11:58:33','2025-12-03 11:58:33'),(3,'Max Super Speciality Hospital','max-hospital-saket','Saket','New Delhi','Delhi','India',4.70,'Multi-Specialty','Max Super Speciality Hospital, Saket is one of the premier names in the healthcare world.','https://images.unsplash.com/photo-1586773860418-d37222d8fce3?auto=format&fit=crop&q=80&w=2073','JCI, NABH','1, 2, Press Enclave Marg, Saket District Centre, Saket, New Delhi, Delhi 110017','+91-11-26515050','info@maxhealthcare.com','https://www.maxhealthcare.in',2006,530,NULL,'15 km',1,'2025-12-03 11:58:33','2025-12-03 11:58:33'),(4,'Artemis Hospital','artemis-hospital','Sector 51','Gurgaon','Haryana','India',4.60,'Multi-Specialty','Artemis Hospital is a state-of-the-art multi-specialty hospital located in Gurgaon.','https://images.unsplash.com/photo-1516549655169-df83a0774514?auto=format&fit=crop&q=80&w=2070','JCI, NABH','Sector 51, Gurugram, Haryana 122001','+91-124-4511111','info@artemishospitals.com','https://www.artemishospitals.com',2007,400,NULL,'20 km',1,'2025-12-03 11:58:33','2025-12-03 11:58:33'),(5,'Fortis Memorial Research Institute','fortis-gurgaon','Sector 44','Gurgaon','Haryana','India',4.80,'Multi-Specialty','Fortis Memorial Research Institute (FMRI) is a multi-super speciality, quaternary care hospital.','https://images.unsplash.com/photo-1512678080530-7760d81faba6?auto=format&fit=crop&q=80&w=2074','JCI, NABH','Sector - 44, Opposite HUDA City Centre, Gurugram, Haryana 122002','+91-124-4962200','enquiry.fmri@fortishealthcare.com','https://www.fortishealthcare.com',2013,1000,NULL,'17 km',1,'2025-12-03 11:58:33','2025-12-03 11:58:33'),(6,'Amrita Hospital','amrita-hospital-kochi','Kochi, Kerala','Kochi','Kerala','India',4.60,'Orthopedics',NULL,NULL,NULL,NULL,'+91 484 280 1234','ortho@amrita.edu',NULL,NULL,NULL,NULL,NULL,1,'2026-02-02 09:30:19','2026-02-02 09:30:19'),(7,'Sarvodaya Hospital','sarvodaya-hospital-faridabad','Faridabad, Delhi NCR','Faridabad','Haryana','India',4.30,'Orthopedics',NULL,NULL,NULL,NULL,'+91 129 414 2000','ortho@sarvodayahospital.com',NULL,NULL,NULL,NULL,NULL,1,'2026-02-02 09:30:19','2026-02-02 09:30:19'),(12,'Max Super Speciality Hospital','max-hospital-shalimar-bagh','Shalimar Bagh, Delhi','Delhi','Delhi','India',4.80,'Oncology',NULL,NULL,NULL,NULL,'+91-11-29814444','oncology@maxhealthcare.com',NULL,NULL,NULL,NULL,NULL,1,'2026-02-02 10:17:55','2026-02-02 10:17:55'),(42,'Indraprastha Apollo Hospital','indraprastha-apollo-hospital','Sarita Vihar, Delhi','New Delhi','Delhi','India',4.90,'Multi-Specialty',NULL,NULL,'NABH Accredited',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-02-04 09:52:20','2026-02-04 09:52:20'),(43,'Max Super Speciality Hospital','max-super-speciality-hospital','Saket, New Delhi','New Delhi','Delhi','India',4.80,'Multi-Specialty',NULL,NULL,'JCI Accredited',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-02-04 09:52:20','2026-02-04 09:52:20'),(44,'Amrita Hospital','amrita-hospital','Faridabad, Haryana','Faridabad','Haryana','India',4.80,'Multi-Specialty',NULL,NULL,'NABH Accredited',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-02-04 09:52:20','2026-02-04 09:52:20'),(45,'Sarvodaya Hospital & Research Centre','sarvodaya-hospital-research-centre','Sector 8, Faridabad','Faridabad','Haryana','India',4.70,'Multi-Specialty',NULL,NULL,'NABH Accredited',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1,'2026-02-04 09:52:20','2026-02-04 09:52:20');
