LOCK TABLES `specialties` WRITE;
/*!40000 ALTER TABLE `specialties` DISABLE KEYS */;
INSERT INTO `specialties` VALUES (1,'Cardiology','cardiology','Comprehensive heart care including surgery and transplants.','Heart',12,'bg-red-50','bg-red-100','text-red-600','https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?auto=format&fit=crop&q=80&w=2070',1,'2025-12-03 11:58:33','2025-12-03 11:58:33'),(2,'Oncology','oncology','Advanced cancer treatment with state-of-the-art technology.','Activity',15,'bg-blue-50','bg-blue-100','text-blue-600','https://images.unsplash.com/photo-1579684385127-1ef15d508118?auto=format&fit=crop&q=80&w=2080',1,'2025-12-03 11:58:33','2025-12-03 11:58:33'),(3,'Orthopedics','orthopedics','Expert care for bones, joints, and spine disorders.','Bone',10,'bg-green-50','bg-green-100','text-green-600','https://images.unsplash.com/photo-1584515933487-9bdb2f989213?auto=format&fit=crop&q=80&w=2069',1,'2025-12-03 11:58:33','2025-12-03 11:58:33'),(4,'Neurology','neurology','Advanced treatment for brain and nervous system disorders.','Brain',8,'bg-purple-50','bg-purple-100','text-purple-600','https://images.unsplash.com/photo-1559757175-5700dde675bc?auto=format&fit=crop&q=80&w=2071',1,'2025-12-03 11:58:33','2025-12-03 11:58:33'),(5,'Gastroenterology','gastroenterology','Digestive health and liver disease management.','Stomach',9,'bg-yellow-50','bg-yellow-100','text-yellow-600','https://images.unsplash.com/photo-1530026405186-ed1f139313f8?auto=format&fit=crop&q=80&w=2070',1,'2025-12-03 11:58:33','2025-12-03 11:58:33'),(6,'Bone Marrow Transplant','bmt','World-class bone marrow transplant facilities.','Dna',5,'bg-indigo-50','bg-indigo-100','text-indigo-600','https://images.unsplash.com/photo-1579165466741-7f35e4755652?auto=format&fit=crop&q=80&w=2079',1,'2025-12-03 11:58:33','2025-12-03 11:58:33'),(7,'GI Surgery','gi-surgery','Gastrointestinal Surgery',NULL,0,NULL,NULL,NULL,NULL,1,'2026-02-04 09:46:08','2026-02-04 09:46:08'),(9,'Orthopaedics','orthopaedics','Orthopaedic Surgery and Joint Replacement',NULL,0,NULL,NULL,NULL,NULL,1,'2026-02-04 09:59:28','2026-02-04 09:59:28'),(11,'Cardiac Sciences','cardiac-sciences','Comprehensive heart care including angioplasty, bypass surgery, valve replacement, and pediatric cardiac surgery','fa-heartbeat',0,NULL,NULL,NULL,NULL,1,'2026-02-04 10:52:50','2026-02-04 10:52:50'),(12,'Bone Marrow Transplant (BMT)','bone-marrow-transplant','Comprehensive BMT services including autologous, allogeneic, haploidentical transplants, CAR-T cell therapy, and cord blood transplants','fa-dna',0,NULL,NULL,NULL,NULL,1,'2026-02-04 11:01:11','2026-02-04 11:01:11'),(14,'Neuro Spine','neuro-spine','Comprehensive neurosurgical and spine care including brain tumor surgery, spine surgery, epilepsy surgery, deep brain stimulation, and endovascular neurosurgery','fa-brain',0,NULL,NULL,NULL,NULL,1,'2026-02-04 11:18:44','2026-02-04 11:18:44'),(18,'Neurospine','neurospine','Institute of Neurosciences - Advanced Neurosurgery and Spine Care','brain',0,NULL,NULL,NULL,NULL,1,'2026-02-04 11:56:50','2026-02-04 11:56:50');
