/*!40000 ALTER TABLE `testimonials` DISABLE KEYS */;
INSERT INTO `testimonials` VALUES (1,2,NULL,'John Doe',55,'USA','CABG',5.00,'Dr. Trehan and his team gave me a new lease on life. The facilities at Medanta are world-class.','https://randomuser.me/api/portraits/men/1.jpg','2023-10-15',1,1,'2025-12-03 11:58:33','2025-12-03 11:58:33'),(2,5,NULL,'Sarah Smith',42,'UK','Angioplasty',5.00,'Excellent care at Fortis. Dr. Seth explained everything clearly and the procedure went smoothly.','https://randomuser.me/api/portraits/women/2.jpg','2023-11-20',1,1,'2025-12-03 11:58:33','2025-12-03 11:58:33'),(3,2,NULL,'Ahmed Al-Fayed',38,'UAE','Liver Transplant',4.80,'My father underwent a liver transplant here. We are very grateful to Dr. Soin.','https://randomuser.me/api/portraits/men/3.jpg','2023-09-05',1,1,'2025-12-03 11:58:33','2025-12-03 11:58:33'),(4,3,NULL,'Maria Garcia',60,'Spain','Knee Replacement',4.90,'I can walk pain-free now thanks to Dr. Marya. Highly recommended.','https://randomuser.me/api/portraits/women/4.jpg','2023-12-01',1,1,'2025-12-03 11:58:33','2025-12-03 11:58:33'),(5,4,NULL,'Mrs. Sunita Gupta',58,'India','Total Knee Replacement',5.00,'Dr. IPS Oberoi performed my bilateral knee replacement with such precision. I was walking within 2 days! The nursing staff was incredibly caring and the physiotherapy team helped me regain full mobility. Six months later, I\'m pain-free and can climb stairs easily.',NULL,'2024-12-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(6,4,NULL,'Mr. James Wilson',34,'Canada','ACL Reconstruction',5.00,'As a professional athlete, I needed the best care for my torn ACL. The sports medicine team at Artemis was exceptional. Dr. Rajiv Yadav used the latest arthroscopic techniques and I was back to competitive sports in 4 months. The cost was 60% less than what I would pay in Canada.',NULL,'2024-11-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(7,4,NULL,'Ms. Sarah Ahmed',42,'UAE','Spinal Fusion Surgery',5.00,'I suffered from chronic back pain for years. Dr. Dheeraj Batheja performed a complex spinal fusion surgery using robotic assistance. The precision was remarkable and my recovery was faster than expected. I\'m now completely pain-free and back to my active lifestyle.',NULL,'2024-10-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(8,4,NULL,'Mr. David Thompson',67,'Australia','Hip Replacement',5.00,'The ceramic-on-ceramic hip replacement by Dr. Vandana Soni has given me a new lease on life. The hospital facilities are world-class and the international patient services made everything seamless. I\'m now walking 5km daily without any discomfort.',NULL,'2024-09-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(9,4,NULL,'Mrs. Fatima Al-Zahra',51,'Qatar','Complex Spine Surgery',5.00,'I had multiple herniated discs and was told I needed complex surgery. Dr. Aditya Gupta\'s expertise in neurosurgery combined with the orthopedic team\'s support resulted in a perfect outcome. The minimally invasive approach meant faster recovery and minimal scarring.',NULL,'2024-08-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(10,2,NULL,'Mrs. Kavita Singh',62,'India','Total Hip Replacement',5.00,'Dr. Suresh Gupta performed my hip replacement surgery with exceptional skill. The multi-specialty approach at Medanta ensured comprehensive care. The nursing staff was professional and the rehabilitation team helped me recover quickly. I\'m now walking pain-free after 3 years of suffering.',NULL,'2024-12-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(11,2,NULL,'Mr. Ahmed Hassan',28,'UAE','Bone Tumor Surgery',5.00,'I was diagnosed with a rare bone tumor in my leg. Dr. Rajeev Verma\'s expertise in orthopedic oncology saved my limb. The limb salvage surgery was complex but successful. The international patient services made my stay comfortable and the cost was reasonable compared to other countries.',NULL,'2024-11-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(12,2,NULL,'Ms. Jennifer Liu',35,'Singapore','Pediatric Spine Surgery',5.00,'My 8-year-old daughter had severe scoliosis. Dr. Amit Kumar performed the spinal correction surgery with remarkable precision. The pediatric care team was amazing with children. The advanced imaging and surgical techniques at Medanta gave us confidence in the treatment.',NULL,'2024-10-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(13,2,NULL,'Mr. Robert Johnson',45,'Canada','Complex Trauma Surgery',5.00,'After a severe accident, I had multiple fractures. Dr. Priya Sharma\'s trauma expertise and the emergency care at Medanta were life-saving. The advanced trauma center and immediate surgical intervention helped me recover completely. I\'m back to my normal activities now.',NULL,'2024-09-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(14,2,NULL,'Mrs. Lisa Thompson',39,'Australia','Sports Medicine Treatment',5.00,'As a professional tennis player, my career was threatened by a complex shoulder injury. Dr. Vikram Singh\'s sports medicine expertise and advanced arthroscopic techniques restored my shoulder function completely. I\'m back to competitive tennis and performing better than before.',NULL,'2024-08-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(15,42,NULL,'Mr. Rajesh Kumar',58,'India','Robotic Knee Replacement',5.00,'Dr. Vikram Sharma performed my knee replacement using robotic technology at Apollo Hospital. The precision was incredible and my recovery was faster than expected. The nursing staff was excellent and the rehabilitation program helped me get back to my daily activities quickly.',NULL,'2024-12-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(16,42,NULL,'Ms. Sarah Johnson',32,'Australia','ACL Reconstruction',5.00,'As a professional athlete, I needed the best care for my ACL injury. Dr. Meera Agarwal\'s expertise in sports medicine was exceptional. The arthroscopic surgery was minimally invasive and the sports rehabilitation program at Apollo got me back to competition level.',NULL,'2024-11-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(17,42,NULL,'Mr. David Wilson',45,'UK','Spinal Fusion Surgery',5.00,'I had severe back pain for years. Dr. Sandeep Singh performed minimally invasive spinal fusion surgery. The advanced imaging and surgical techniques at Apollo were impressive. I\'m now pain-free and back to my normal activities.',NULL,'2024-10-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(18,42,NULL,'Mrs. Priya Patel',65,'Canada','Hip Replacement Surgery',5.00,'Dr. Raju Vaishya is an exceptional surgeon. My hip replacement surgery was performed with great skill and care. The international patient services at Apollo made my entire journey smooth. The hospital facilities are world-class and I\'m very satisfied with the results.',NULL,'2024-09-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(19,42,NULL,'Mr. Ahmed Al-Rashid',41,'UAE','Joint Replacement Surgery',5.00,'Dr. Ashish Dagar performed my complex hip revision surgery with remarkable expertise. The robotic precision and comprehensive care at Apollo exceeded my expectations. I\'m now able to walk without pain and have returned to an active lifestyle.',NULL,'2024-08-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(20,43,NULL,'Mr. Suresh Gupta',62,'India','Hip Replacement Surgery',5.00,'Dr. H.N Bajaj performed my hip replacement at Max Hospital with exceptional skill. The computer-assisted surgery was precise and my recovery was remarkable. The nursing staff provided excellent care and the rehabilitation program was comprehensive.',NULL,'2024-12-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(21,43,NULL,'Ms. Jennifer Lee',28,'Singapore','Trauma Surgery',5.00,'After a serious accident, Dr. Priya Jaisingh saved my leg with expert trauma surgery at Max Hospital. The emergency response was immediate and the surgical outcome was excellent. I\'m grateful for the world-class trauma care I received.',NULL,'2024-11-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(22,43,NULL,'Mr. Robert Brown',52,'USA','Spine Surgery',5.00,'Dr. Harshavardhan Hegde performed complex spine surgery using neuro-navigation technology. The precision was incredible and my chronic back pain is completely gone. Max Hospital\'s spine center is truly world-class.',NULL,'2024-10-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(23,43,NULL,'Mrs. Anita Sharma',45,'UAE','Knee Arthroscopy',5.00,'Dr. Amit Bhargava performed arthroscopic knee surgery with minimal invasion. The recovery was faster than expected and I\'m back to my active lifestyle. The international patient services at Max were outstanding.',NULL,'2024-09-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(24,43,NULL,'Mr. Mark Williams',56,'UK','Computer-Assisted Surgery',5.00,'Dr. Ramneek Mahajan used computer navigation for my complex joint replacement. The precision technology and personalized care at Max Hospital exceeded all expectations. I\'m amazed by the advanced surgical capabilities and excellent outcomes.',NULL,'2024-08-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(25,44,NULL,'Mr. Krishnan Nair',59,'India','Hip Replacement Surgery',5.00,'Dr. Sandeep Vaishya performed my hip replacement at Amrita Hospital with exceptional care. The minimally invasive approach reduced my recovery time significantly. The holistic care approach and spiritual environment at Amrita made my healing journey peaceful and effective.',NULL,'2024-12-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(26,44,NULL,'Ms. Fatima Al-Zahra',8,'UAE','Pediatric Spine Surgery',5.00,'Dr. Priya Nair corrected my daughter\'s spinal deformity with incredible skill and compassion. The pediatric team at Amrita Hospital made the entire experience comfortable for our family. The child-friendly environment and excellent post-operative care exceeded our expectations.',NULL,'2024-11-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(27,44,NULL,'Mr. James Wilson',48,'Canada','Spine Surgery',5.00,'Dr. Ravi Suman Reddy performed complex spine surgery using minimally invasive techniques. The integration of modern medicine with traditional healing practices at Amrita Hospital provided a unique and effective treatment experience. I\'m completely pain-free now.',NULL,'2024-10-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(28,44,NULL,'Mrs. Lakshmi Devi',52,'Malaysia','Knee Arthroscopy',5.00,'Dr. Ashok Kumar performed arthroscopic knee surgery with minimal invasion. The spiritual healing environment at Amrita Hospital complemented the medical treatment perfectly. The compassionate care and excellent facilities made my recovery smooth and comfortable.',NULL,'2024-09-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(29,44,NULL,'Mr. Robert Chen',44,'Singapore','Holistic Joint Treatment',5.00,'Dr. Maya Krishnan\'s integrative approach combining modern surgery with traditional healing was remarkable. The mind-body healing program at Amrita Hospital addressed not just my physical condition but my overall wellness. The results exceeded all expectations.',NULL,'2024-08-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(30,45,NULL,'Mr. Ravi Patel',62,'India','Hip Replacement Surgery',5.00,'Dr. Rajesh Kumar performed my hip replacement at Sarvodaya Hospital with exceptional skill. The compassionate care and advanced facilities made my recovery smooth. The hospital\'s commitment to patient welfare is truly commendable.',NULL,'2024-12-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(31,45,NULL,'Ms. Sarah Johnson',35,'USA','ACL Reconstruction',5.00,'Dr. Amit Verma\'s expertise in sports medicine helped me return to my athletic career. The minimally invasive approach and excellent rehabilitation program at Sarvodaya Hospital exceeded my expectations. I\'m back to playing tennis professionally.',NULL,'2024-11-15',1,1,'2026-02-04 09:59:29','2026-02-04 09:59:29'),(32,45,NULL,'Mr. Ahmed Al-Rashid',55,'UAE','Spine Surgery',5.00,'Dr. Priya Sharma performed complex spine surgery with remarkable precision. The state-of-the-art facilities and compassio